import { describe, expect, it } from "vitest";
import { Sync, type SyncResponse } from "./index.ts";
import { ClientState } from "../indexeddb/clientState.ts";
import { RowStore } from "../indexeddb/rowStore.ts";
import { OperationLog } from "../indexeddb/operationLog.ts";

// Generated by the production OCaml encoder/hash, not the client under test.
function serverCheckpoint(): SyncResponse {
  return {
    protocolVersion: 3, clientId: "reader", baseServerVersion: 0,
    latestServerVersion: 9, lastMutationID: 4,
    operations: [{
      type: "checkpointRow", tableName: "todos", rowKey: "r1",
      dot: { clientId: "checkpoint:todos:r1", version: 9 }, checkpointSeenServerVersion: 8,
      fields: {
        title: { value: "Hi", dot: { clientId: "client-1", version: 3 } },
        numbers: { value: [0.000001, 1e-7, 1e20], dot: { clientId: "client-1", version: 3 } },
      },
      tombstone: { dot: { clientId: "deleter", version: 3 }, versionVector: { "client-1": 2 } },
      serverVersion: 9,
    }],
    responseHash: "87dc05ab1b0b1a0b28433266924ea61c89870c5a496cf402ce7fe9795a7b462f",
  };
}

const sync = new Sync(new ClientState(), new RowStore([]), new OperationLog());
describe("Sync response hash compatibility", () => {
  it("matches a real server checkpoint with fractional and large numbers", async () => {
    await expect(sync.validateResponseHash(serverCheckpoint())).resolves.toBe(true);
  });

  it("protects the acknowledged mutation frontier", async () => {
    const response = serverCheckpoint();
    response.lastMutationID = 5;
    await expect(sync.validateResponseHash(response)).resolves.toBe(false);
  });

  it("ignores JSON object key insertion order", async () => {
    const response = serverCheckpoint();
    const operation = response.operations[0];
    if (operation.type !== "checkpointRow") {
      throw new Error("Expected checkpoint fixture");
    }
    const fields = operation.fields;
    operation.fields = { numbers: fields.numbers, title: fields.title };
    await expect(sync.validateResponseHash(response)).resolves.toBe(true);
  });
});
